#[value(rename_all = "camelCase", deny_unknown_fields)]
pub struct IoEntryDescriptor {
    pub from: ArtifactDialect,
    pub into: ArtifactDialect,
    pub fidelity: IoFidelity,
    pub sniffs: bool,
