//! 🧪️ Independent `syn` facts for the base mutation declaration contract.

use serde::{Deserialize, Serialize};
use syn::{Item, TraitItem};

#[derive(Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
struct MutationTraitFacts {
    descriptors_has_initializer: bool,
    descriptor_has_default_body: bool,
    sentinel_present: bool,
}

#[derive(Deserialize)]
struct NeutralFacts {
    cases: Vec<NeutralCase>,
}

#[derive(Deserialize)]
struct NeutralCase {
    id: String,
    subject: String,
    category: String,
    facts: MutationTraitFacts,
}

fn mutation_trait_facts(source: &str) -> MutationTraitFacts {
    let file = syn::parse_file(source).expect("actual mutation source must parse");
    let mutations: Vec<_> = file.items.iter().filter_map(|item| match item {
        Item::Trait(item) if matches!(&item.vis, syn::Visibility::Public(_)) && item.ident == "Mutation" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(mutations.len(), 1, "actual source must contain exactly one public Mutation trait");
    let mutation = mutations[0];
    let descriptors: Vec<_> = mutation.items.iter().filter_map(|item| match item {
        TraitItem::Const(item) if item.ident == "DESCRIPTORS" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(descriptors.len(), 1, "Mutation must contain exactly one DESCRIPTORS associated constant");
    let descriptors_has_initializer = descriptors[0].default.is_some();
    let descriptor: Vec<_> = mutation.items.iter().filter_map(|item| match item {
        TraitItem::Fn(item) if item.sig.ident == "descriptor" => Some(item),
        _ => None,
    }).collect();
    assert_eq!(descriptor.len(), 1, "Mutation must contain exactly one descriptor associated method");
    let descriptor_has_default_body = descriptor[0].default.is_some();
    let sentinels = file.items.iter().filter(|item| matches!(item, Item::Const(item) if item.ident == "UNDECLARED_MUTATION_LEAF")).count();
    MutationTraitFacts { descriptors_has_initializer, descriptor_has_default_body, sentinel_present: sentinels != 0 }
}

#[test]
fn mutation_trait_matches_adjacent_required_declaration_facts() {
    let neutral: NeutralFacts = serde_json::from_str(include_str!("../../🧫️fixtures/🪪️mandatory-mutation-descriptor/🔣️.json")).expect("adjacent neutral vector must parse");
    let expected = neutral.cases.into_iter().find(|case| case.id == "required-items-accepted").expect("neutral vector must contain required-items-accepted");
    assert_eq!(expected.subject, "mutation-trait-facts");
    assert_eq!(expected.category, "required-associated-items");
    let actual = mutation_trait_facts(include_str!("../../../../../../../🔨️modules/📡️replication/🎮️mutation/🦀️.rs"));
    println!("actual={} expected={}", serde_json::to_string(&actual).expect("actual facts serialize"), serde_json::to_string(&expected.facts).expect("expected facts serialize"));
    assert_eq!(actual, expected.facts);
}

//! 🧪️ Third-party Syn parses the crate root and the facade against one language-neutral export
//! roster. `#[proc_macro_derive]` can only be tagged at the proc-macro crate root (rustc requires
//! it), so the owner `🦀️.rs` — pure implementation, no crate — must register none.
use std::collections::BTreeSet;

fn registered(source: &str) -> BTreeSet<String> {
    let file = syn::parse_file(source).unwrap();
    file.items.iter().flat_map(|item| match item { syn::Item::Fn(item) => item.attrs.as_slice(), _ => &[] }).filter_map(|attribute| {
        if !attribute.path().is_ident("proc_macro_derive") { return None; }
        let args = attribute.parse_args_with(syn::punctuated::Punctuated::<syn::Meta, syn::Token![,]>::parse_terminated).unwrap();
        match args.first().unwrap() { syn::Meta::Path(path) => Some(path.get_ident().unwrap().to_string()), _ => panic!("derive name is not an identifier") }
    }).collect()
}

#[test]
fn facade_exports_match_registered_macros() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/📤️macro-exports/🔣️.json")).unwrap();
    let expected = |field: &str| fixture[field].as_array().unwrap().iter().map(|name| name.as_str().unwrap().to_owned()).collect::<BTreeSet<_>>();
    let owner = registered(include_str!("../../🦀️.rs"));
    let compiled = registered(include_str!("../../📦️packages/🦀️rust/🦀️.rs"));
    assert_eq!(owner, BTreeSet::new(), "owner component.rs must hold implementation only, no crate-root derive tags");
    assert_eq!(compiled, expected("registeredDerives"));
    let facade = syn::parse_file(include_str!("../../../🦀️.rs")).unwrap();
    let exports: BTreeSet<_> = facade.items.iter().filter_map(|item| match item { syn::Item::Use(item) => Some(&item.tree), _ => None }).filter_map(|tree| match tree { syn::UseTree::Path(path) if path.ident == "dsl_derive" => Some(path.tree.as_ref()), _ => None }).flat_map(|tree| match tree { syn::UseTree::Group(group) => group.items.iter().collect::<Vec<_>>(), _ => panic!("facade derive exports must be explicit") }).map(|tree| match tree { syn::UseTree::Name(name) => name.ident.to_string(), _ => panic!("facade derive exports must be named") }).collect();
    assert_eq!(exports, expected("facadeExports"));
    assert!(exports.is_subset(&compiled));
    assert!(expected("traitOnly").is_disjoint(&compiled));
}

